import http from 'k6/http';
import { fail } from 'k6';

export const options = {
  vus: 1,
  iterations: 1,
};

const baseURL = __ENV.BASE_URL.replace(/\/+$/, '');

function requireSuccess(response, path) {
  if (response.status < 200 || response.status >= 300) {
    fail(`${path} returned status ${response.status}`);
  }
}

export default function () {
  const login = http.post(
    `${baseURL}/login`,
    JSON.stringify({ username: 'bench', password: 'bench' }),
    { headers: { 'Content-Type': 'application/json' } }
  );
  requireSuccess(login, '/login');

  const csrf = login.json('csrf');
  if (typeof csrf !== 'string' || csrf.length === 0) {
    fail('/login did not return a CSRF token');
  }

  requireSuccess(http.get(`${baseURL}/products`), '/products');

  const params = {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  };

  requireSuccess(
    http.post(`${baseURL}/cart`, JSON.stringify({ product_id: 'sku-1' }), params),
    '/cart'
  );
  requireSuccess(http.post(`${baseURL}/checkout`, '{}', params), '/checkout');
}
